import torch
import torch_npu

def run(boxes, scores, max_output_size, iou_threshold, scores_threshold, pad_to_max_output_size=False):
    iou_threshold_tensor = torch.tensor(iou_threshold, dtype=torch.float32, device=boxes.device)
    scores_threshold_tensor = torch.tensor(scores_threshold, dtype=torch.float32, device=boxes.device)
    return torch_npu.npu_nms_v4(boxes, scores, max_output_size, iou_threshold_tensor, scores_threshold_tensor, pad_to_max_output_size=pad_to_max_output_size)
